/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const pending = new Map();
const feed = createProgressFeed({initialPacket: 'initial', decode: packet => packet === 'initial' ? {value: 0} : new Promise(resolve => pending.set(packet, resolve))});
const records = [], shown = [], queues = [], notices = [], cancels = [];
const workspace = createTransferWorkspace({transport: () => {}, onCancel: x => cancels.push(x.attemptId), record: x => queues.push(x), showQueued: x => notices.push(x), recordProgress: x => records.push(x), showProgress: x => shown.push(x)});
const file = {id: 'f', progressFeed: feed};
workspace.select(file);
assert.deepEqual(shown.map(x => x.frame.value), [0]);
assert.deepEqual(records.map(x => x.frame.value), [0]);
feed.emit('first'); feed.emit('second');
pending.get('second')({value: 2});
await Promise.resolve();
pending.get('first')({value: 1});
await Promise.resolve();
assert.deepEqual(shown.map(x => x.frame.value), [0, 2]);
assert.deepEqual(records.map(x => x.frame.value), [0, 2, 1]);
feed.emit('third'); pending.get('third')({value: 3}); await Promise.resolve();
assert.deepEqual(shown.map(x => x.frame.value), [0, 2, 3]);
workspace.hide();
assert.deepEqual(cancels, [1]);
workspace.select(file);
assert.deepEqual(shown.map(x => x.frame.value), [0, 2, 3, 0]);
workspace.retry();
assert.deepEqual(queues.map(x => x.kind), ['select', 'select', 'retry']);
assert.equal(notices.length, 3);
workspace.dispose();
const deltas = [];
const stop = collectProgressTelemetry(createProgressFeed({initialPacket: 'cached'}), x => deltas.push(x));
assert.deepEqual(deltas, []);
stop();
console.log('progress checks passed');
EOF"

/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed } from './src/workspace.js';
let workspace;
const shown = [], cancelled = [];
const feed = createProgressFeed({initialPacket: 'cached', onDetach: () => workspace.select({id: 'next'})});
workspace = createTransferWorkspace({transport: () => {}, onCancel: x => cancelled.push(x.attemptId), record: () => {}, showQueued: () => {}, recordProgress: () => {}, showProgress: x => { shown.push(x.frame); if (x.frame === 'cached') workspace.hide(); }});
workspace.select({id: 'first', progressFeed: feed});
assert.deepEqual(shown, ['cached']);
assert.deepEqual(cancelled, [1]);
assert.equal(workspace.snapshot().fileId, 'next');
console.log('synchronous reentry check passed');
EOF"

